// SPDX-License-Identifier: MIT
  pragma solidity ^0.8.20;

  contract EIP7702AccountLogic {
      event DebugInfo(address thisAddress, uint256 balance, address to, uint256 amount);
      event TransferAttempt(address to, uint256 amount, bool success);

      function sendNative(
          address payable to,
          uint256 amount
      ) external {
          // 记录调试信息
          emit DebugInfo(address(this), address(this).balance, to, amount);

          // 检查余额
          require(address(this).balance >= amount, "Insufficient balance");

          // 尝试转账并记录结果
          (bool success, ) = to.call{value: amount}("");
          emit TransferAttempt(to, amount, success);

          require(success, "Transfer failed");
      }
  }

